def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    man_patches = image_patch.find("man")
    hand_patches = image_patch.find("hand")

    if not man_patches or not hand_patches:
        return image_patch

    man_centers = [(p.left + p.right) / 2, (p.upper + p.lower) / 2 for p in man_patches]
    hand_centers = [(p.left + p.right) / 2, (p.upper + p.lower) / 2 for p in hand_patches]

    man_hand_pairs = []
    for man_center in man_centers:
        for hand_center in hand_centers:
            if abs(man_center[0] - hand_center[0]) < 50 and abs(man_center[1] - hand_center[1]) < 50:
                man_hand_pairs.append((man_center, hand_center))

    if not man_hand_pairs:
        return image_patch

    man_with_hands_up = max(man_hand_pairs, key=lambda pair: abs(pair[1][1] - pair[0][1]))
    return next(p for p in man_patches if (p.left + p.right) / 2 == man_with_hands_up[0][0])

